using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class UnitDirectiveTests
{
 static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
 static NewMilitaryInput Input(WorldSession s,NewMilitaryAction action)=>new(new("request:unit-recipient/"+s.Revision+"/"+action),action);
 static void Send(WorldSession s,NewMilitaryAction action,long amount=0){var result=s.DecideNewMilitary(Input(s,action) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);}
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static WorldSession Away(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{ObservationPolicy=NewGameMilitary.ObservationContract},s.PlayerControl,s.Revision).Code);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+90000,a.Y-10000),B=new(a.X+90000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Max(l=>l.EndAt)+1);return s;}
 static NewMilitaryInput Query(WorldSession s,int unit)=>Input(s,NewMilitaryAction.InquireUnitKnown) with{InquiryTarget=new(NewGameMilitary.UnitRecipientContract,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[unit])!),PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};
 static TroopDispatch Dispatch(WorldSession s,int unit){var i=Query(s,unit);var r=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();}
 static UnitPostInquiryAnswer Answer(ContractWorld w,TroopReceipt receipt)=>ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==receipt.ReplyMessage).Body));

 static NewMilitaryInput Directive(WorldSession s,int unit,UnitDirectiveKind kind){var w=s.DiagnosticSnapshot();var k=NewGameMilitary.SelectKnownTarget(w,NewGameMilitary.UnitIds[unit])!;return Input(s,NewMilitaryAction.SendUnitDirective) with{Directive=new(NewGameMilitary.UnitDirectiveContract,k,kind,kind==UnitDirectiveKind.Move?new(k.Position.X+8000,k.Position.Y):null),DeliverBy=s.Seconds+600,PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};}
 [Theory][InlineData(0,UnitDirectiveKind.Move)][InlineData(1,UnitDirectiveKind.Move)][InlineData(2,UnitDirectiveKind.Move)][InlineData(0,UnitDirectiveKind.Hold)][InlineData(1,UnitDirectiveKind.Hold)][InlineData(2,UnitDirectiveKind.Hold)][InlineData(0,UnitDirectiveKind.Recall)][InlineData(1,UnitDirectiveKind.Recall)][InlineData(2,UnitDirectiveKind.Recall)]
 public void PhysicalReceiptMovesOnlyTheSelectedUnit(int index,UnitDirectiveKind kind){var s=Away();var input=Directive(s,index,kind);var before=s.DiagnosticSnapshot();int orders=before.NewMilitary!.Orders.Length;var result=s.DecideNewMilitary(input,s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);var d=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();Assert.Equal(input.Directive!.Known.Position,d.Destination);Assert.Equal(orders,s.DiagnosticSnapshot().NewMilitary!.Orders.Length);At(s,d.DueAt-1);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,d.DueAt);var w=s.DiagnosticSnapshot();var receipt=w.NewMilitary!.UnitDirective!.Receipts.Last();Assert.True(receipt.Delivered);Assert.True(receipt.Applied);Assert.False(MessageFlow.Knows(w.Messaging,receipt.ReplyMessage,w.PlayerControl.Value));var order=w.NewMilitary.Orders.Last();Assert.Equal(new[]{index},order.AffectedUnits);long end=order.Routes[index].LastOrDefault()?.EndAt??s.Seconds;foreach(int other in Enumerable.Range(0,3).Where(i=>i!=index))for(long t=s.Seconds;t<=end+2;t++)Assert.Equal(NewGameMilitary.Position(before,other,t),NewGameMilitary.Position(w,other,t));if(kind==UnitDirectiveKind.Hold)Assert.Empty(order.Routes[index]);else Assert.Equal(kind==UnitDirectiveKind.Move?input.Directive.Goal:NewGameMilitary.Home(w,index),order.Routes[index].Last().To);foreach(var v in new[]{s,restored})At(v,Math.Max(end+1,receipt.ReplyDueAt));Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));new WorldSession(s.DiagnosticSnapshot());}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)]public void InvalidDirectiveIsAtomic(int variant){var s=Away();var i=Directive(s,1,UnitDirectiveKind.Move);var x=i.Directive!;i=variant switch{0=>i with{Directive=x with{Contract="unknown"}},1=>i with{Directive=x with{Known=x.Known with{Unit=new("unit:unknown")}}},2=>i with{Directive=x with{Known=x.Known with{ObservedAt=x.Known.ObservedAt+1}}},3=>i with{Directive=x with{Known=x.Known with{Evidence="false"}}},4=>i with{Directive=x with{Known=x.Known with{Position=new(x.Known.Position.X+1,x.Known.Position.Y)}}},5=>i with{Directive=x with{Kind=(UnitDirectiveKind)99}},6=>i with{Directive=x with{Goal=null}},_=>i with{Directive=x with{Kind=UnitDirectiveKind.Hold}}};string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Fact]public void SameDirectiveRequestNeverExecutesTwice(){var s=Away();var input=Directive(s,1,UnitDirectiveKind.Move);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);var d=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,d.DueAt);var before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Fact]public void SavedScopeTamperingIsRejected(){var s=Away();var i=Directive(s,2,UnitDirectiveKind.Move);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last().DueAt);var w=s.DiagnosticSnapshot();w.NewMilitary!.Orders[^1]=w.NewMilitary.Orders[^1] with{AffectedUnits=[0]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
 [Fact]public void LegacySaveOmitsDirectiveAndScope(){var s=Away();string text=System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DiagnosticSnapshot().NewMilitary));Assert.DoesNotContain("UnitDirective",text);Assert.DoesNotContain("AffectedUnits",text);new WorldSession(s.DiagnosticSnapshot());}

 static void NearWing(WorldSession s){var known=NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[1])!;Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=known.Position,KnownTarget=known},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);}
 [Theory][InlineData(false)][InlineData(true)]public void OriginalIssueOrderSurvivesReversedPhysicalArrival(bool recallIssuedLater){var s=Away();NearWing(s);NewMilitaryInput i;if(recallIssuedLater){i=Directive(s,1,UnitDirectiveKind.Move);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.RemoteRecall);}else{Send(s,NewMilitaryAction.RemoteRecall);i=Directive(s,1,UnitDirectiveKind.Move);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);}var w=s.DiagnosticSnapshot();var wing=w.NewMilitary!.UnitDirective!.Dispatches.Last();var all=w.NewMilitary.Withdrawal!.Dispatches.Last();Assert.True(wing.DueAt<all.DueAt);At(s,wing.DueAt);Assert.True(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Last().Applied);At(s,all.DueAt);w=s.DiagnosticSnapshot();Assert.True(w.NewMilitary!.Withdrawal!.Receipts.Last().Applied);var recall=w.NewMilitary.Orders.Last();Assert.Equal(recallIssuedLater?new[]{0,1,2}:new[]{0,2},recall.AffectedUnits);var wingOrder=w.NewMilitary.Orders.Single(o=>o.Action==NewMilitaryAction.SendUnitDirective);long end=wingOrder.Routes[1].Last().EndAt;Assert.Equal(recallIssuedLater?NewGameMilitary.Home(w,1):i.Directive!.Goal,NewGameMilitary.Position(w,1,Math.Max(end,recall.Routes[1].LastOrDefault()?.EndAt??0)+1));new WorldSession(w);}

 [Fact]public void CancelOldArmyRecallPreservesNewMainPostHold(){var s=Away();var known=NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[0])!;Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=known.Position,KnownTarget=known},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);Send(s,NewMilitaryAction.RemoteRecall);var directive=Directive(s,0,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(directive,s.PlayerControl,s.Revision).Code);var w=s.DiagnosticSnapshot();var recall=w.NewMilitary!.Withdrawal!.Dispatches.Last();var local=w.NewMilitary.UnitDirective!.Dispatches.Last();Assert.Equal(recall.DueAt,local.DueAt);At(s,recall.DueAt);w=s.DiagnosticSnapshot();Assert.True(w.NewMilitary!.UnitDirective!.Receipts.Last().Applied);var held=w.NewMilitary.Orders.Last();Assert.Equal(new[]{0},held.AffectedUnits);var cancel=Input(s,NewMilitaryAction.CancelRecallKnown) with{TargetOriginal=recall.Id};Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(cancel,s.PlayerControl,s.Revision).Code);var due=s.DiagnosticSnapshot().NewMilitary!.Cancellation!.Dispatches.Last().DueAt;At(s,due-1);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,due);w=s.DiagnosticSnapshot();var effect=w.NewMilitary!.Cancellation!.Effects.Last();Assert.Equal(UnitCancelDisposition.Stopped,effect.Outcome);var stop=w.NewMilitary.Orders.Single(o=>o.Id==effect.StopOrder);Assert.Equal(new[]{1,2},stop.AffectedUnits);for(int n=0;n<3;n++)Assert.Equal(NewGameMilitary.Position(w,n,s.Seconds),NewGameMilitary.Position(w,n,s.Seconds+20));foreach(var v in new[]{s,restored})At(v,v.Seconds+20);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));new WorldSession(s.DiagnosticSnapshot());}
 [Fact]public void StaleDirectiveDoesNotFollowAUnitAlreadyLeaving(){var s=Away();Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var input=Directive(s,2,UnitDirectiveKind.Move);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);var d=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();int orders=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;At(s,d.DueAt);var w=s.DiagnosticSnapshot();var receipt=w.NewMilitary!.UnitDirective!.Receipts.Last();Assert.False(receipt.Delivered);Assert.False(receipt.Applied);Assert.Empty(w.NewMilitary.UnitDirective.Effects);Assert.Equal(orders,w.NewMilitary.Orders.Length);Assert.False(MessageFlow.FailureKnown(w.Messaging,d.Attempt,w.PlayerControl.Value));At(s,receipt.ReplyDueAt);w=s.DiagnosticSnapshot();Assert.True(MessageFlow.FailureKnown(w.Messaging,d.Attempt,w.PlayerControl.Value));new WorldSession(w);}
 [Fact]public void ExpiredDirectiveNeverExecutes(){var s=Away();var i=Directive(s,1,UnitDirectiveKind.Move) with{DeliverBy=s.Seconds+1};Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var d=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,d.DueAt);var w=s.DiagnosticSnapshot();var r=w.NewMilitary!.UnitDirective!.Receipts.Last();Assert.False(r.Delivered);Assert.False(r.Applied);Assert.Equal(AttemptStatus.Rejected,r.ArrivalStatus);Assert.Empty(w.NewMilitary.UnitDirective.Effects);new WorldSession(w);}
 [Fact]public void AppliedDirectiveReplyRecoversThroughItsOwnWing(){var s=Away();var i=Directive(s,2,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var d=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,d.DueAt);var r=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Last();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(a.X-20000,a.Y)},s.PlayerControl,s.Revision).Code);At(s,r.ReplyDueAt);var w=s.DiagnosticSnapshot();Assert.False(MessageFlow.Knows(w.Messaging,r.ReplyMessage,w.PlayerControl.Value));var failure=w.NewMilitary!.ReplyRecovery!.Flights.Last(f=>f.Kind==UnitReplyLeg.FailureReport);At(s,failure.DueAt);w=s.DiagnosticSnapshot();Assert.True(MessageFlow.Knows(w.Messaging,failure.Message,d.Recipient.Value));var retry=w.NewMilitary!.ReplyRecovery!.Flights.Last(f=>f.Kind==UnitReplyLeg.Retry);Send(s,NewMilitaryAction.PersonalHome);At(s,retry.DueAt);w=s.DiagnosticSnapshot();Assert.True(MessageFlow.Knows(w.Messaging,r.ReplyMessage,w.PlayerControl.Value));Assert.Single(w.NewMilitary!.UnitDirective!.Effects);Assert.Single(w.NewMilitary.Orders,o=>o.Action==NewMilitaryAction.SendUnitDirective);new WorldSession(w);}
 [Fact]public void DirectiveReplyBodyCannotBeForgedInSave(){var s=Away();var i=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last().DueAt);var w=s.DiagnosticSnapshot();string id=w.NewMilitary!.UnitDirective!.Receipts.Last().ReplyMessage;w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id==id?m with{Body="{}"}:m).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
}
